package repository

type Product struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Category string `json:"category"`
	Price    int    `json:"price"`
}

type ProductRepository struct {
	products []Product
}

func NewProductRepository() *ProductRepository {
	return &ProductRepository{products: []Product{
		{ID: 1, Name: "Steel Hammer", Category: "tools", Price: 25},
		{ID: 2, Name: "Rubber Mallet", Category: "tools", Price: 15},
		{ID: 3, Name: "Garden Hose", Category: "garden", Price: 40},
		{ID: 4, Name: "Steel Rake", Category: "garden", Price: 30},
	}}
}

func (r *ProductRepository) List() []Product {
	return r.products
}

