package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"sort"
	"testing"
)

func ids(path string) []int {
	r := SetupRouter()
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", path, nil))
	var list []map[string]interface{}
	json.Unmarshal(w.Body.Bytes(), &list)
	out := []int{}
	for _, p := range list {
		out = append(out, int(p["id"].(float64)))
	}
	sort.Ints(out)
	return out
}

func eq(t *testing.T, got, want []int) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("got %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("got %v, want %v", got, want)
		}
	}
}

func TestProductFilters(t *testing.T) {
	eq(t, ids("/products"), []int{1, 2, 3, 4})
	eq(t, ids("/products?category=garden"), []int{3, 4})
	eq(t, ids("/products?maxPrice=25"), []int{1, 2})
	eq(t, ids("/products?category=garden&maxPrice=35"), []int{4})
}

func TestProductStatus(t *testing.T) {
	r := SetupRouter()
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/products", nil))
	if w.Code != http.StatusOK {
		t.Fatalf("status %d", w.Code)
	}
}

